/// Editorial recommendations from HorizonXI Wiki EXP Camps, checked 2026-10-30.
/// Camp facts are sourced; ranking is provisional and has not been tested in game.
enum PartyLevelingGuide {
    static let guide = Guide(name: "Party Guide - HorizonXI",
        desc: "Draft • Six-player camps with two backups. Recommendations are provisional; check party sync, access and competition. Unlisted levels: stay only while kills remain efficient or choose a compatible listed sync. Levels 1–11: use the Solo Guide.",
        levels: "12–75 DRAFT", steps: [
            GuideStep(kind: "L", title: "Levels 12–14", note: "Recommended: Valkurm Dunes D-7/E-6/E-7: Hill Lizard.\nBackup 1: Buburimu Peninsula E-7/E-9/F-8: Sylvestre, Mighty Rarab.\nBackup 2: Inner Horutoto Ruins F-10/F-11: Beady Beetle, Bat Battalion.\nTurn away from lizard petrification; avoid links in the ruins.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 14–16", note: "Recommended: Valkurm Dunes B-7/F-7/F-9: Snipper, Damselfly.\nBackup 1: Buburimu Peninsula G-6: Cape Coney, Cactus Bee.\nBackup 2: Ordelle’s Caves H-7: Hognosed Bat, Fly Agaric (wiki 14–17).\nBring poison and silence recovery; control bat links.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 17–19", note: "Recommended: Valkurm Dunes B-7/E-9/I-9: Snipper, Beach Pugil.\nBackup 1: Sauromugue Champaign K-9: Hill Lizard, bats.\nBackup 2: Ordelle’s Caves F-10: Dung Beetle, goblins.\nUse crabs first at 17; check fish carefully. Goblins can link.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 19–21", note: "Recommended: Qufim Island H-7/I-8: Land Worm, Clipper.\nBackup 1: Carpenters’ Landing H-6 docks: orcs, Fosse Pugil, Forest Tiger.\nBackup 2: Davoi J-7 entrance: orcs.\nLeave Qufim’s pond before undead spawn at night. Landing access is via Jugner E-6.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 22–24", note: "Recommended: Qufim Island G-6/H-6: Greater Pugil, giants.\nBackup 1: Lower Delkfutt’s Tower H-10 entrance: bats, goblins, giants.\nBackup 2: Carpenters’ Landing I-11/I-12 caves: Diving Beetle, Shrieker.\nPrefer manageable fish over hard-hitting giants; reach Landing via Jugner J-8.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 25–27", note: "Recommended: Yuhtunga Jungle H-6/G-6/G-7: Yuhtunga Mandragora.\nBackup 1: Sauromugue Champaign F-8/G-8: Diving Beetle, Tabar Beak.\nBackup 2: Carpenters’ Landing J-10 docks: Spinous Pugil, Sabretooth Tiger, Birdtrap (wiki 24–27).\nKazham access required for primary. Watch patrolling goblins; bring paralysis recovery for tigers.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 30–33", note: "Recommended: Bibiki Bay, Purgonorgo Isle: Jagil, Coastal Opo-opo.\nBackup 1: Attohwa Chasm I-9/I-10: Gallinipper.\nBackup 2: Sea Serpent Grotto map 1 J-10: Sahagin, bats, Ironshell.\nTake Manaclipper to the island; avoid Urganite. Grotto needs Kazham access and careful sound pulls.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 35–37", note: "Recommended: Crawlers’ Nest I-9/K-8: Worker Crawler.\nBackup 1: Garlaige Citadel G-7/G-8: Siege Bat, Borer Beetle.\nBackup 2: Western Altepa Desert L-6/M-8: Desert Spider.\nCounter crawler defense boosts; manage bat links; spider backup needs Erase for area slow.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 40–41", note: "Recommended: Crawlers’ Nest map 2 H-9 / map 3 I-8: Soldier Crawler.\nBackup 1: Gustav Tunnel K-7, Valkurm side: Hell Bats, Hawker (wiki 39–42).\nBackup 2: Garlaige Citadel G-8 behind gate 1: Citadel Bats (wiki 39–41).\nBring Dispel for crawlers. Gate 1 needs four players on switches; bats can link.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 43–45", note: "Recommended: Crawlers’ Nest map 2 H-7: Labyrinth Lizard.\nBackup 1: Yhoator Jungle H-6, Ifrit zones: Goblin Bouncer, Goblin Hunter.\nBackup 2: Toraimarai Canal map 1 F-9: Bigclaw, Makara.\nControl lizard links; stun bombs. Canal requires Portal Charm/three-mage access or Rhinostery Certificate and Sneak.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 49–50", note: "Recommended: Garlaige Citadel F-8 basement: Chamber Beetle.\nBackup 1: Crawlers’ Nest F-6/G-6: Dragonfly, Den Beetle.\nBackup 2: Quicksand Caves H-9, enter Western Altepa J-9: Helm Beetle, anticans.\nBring Dispel, Sneak and Echo Drops; cave monsters have a wide level spread.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 52–54", note: "Recommended: Uleguerand Range G-11: Variable Hare, Uleguerand Tiger.\nBackup 1: Crawlers’ Nest F-9: Helm Beetle (wiki 51–54).\nBackup 2: Toraimarai Canal G-7/F-10: Canal Pugil, Scavenger Crab (wiki 50–54).\nBring paralysis recovery for tigers, Dispel for beetles/crabs. Canal needs access and Sneak.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 54–56", note: "Recommended: Kuftal Tunnel J-7/I-8/G-3: Robber Crab.\nBackup 1: Crawlers’ Nest E-7: Crawler Hunter, Knight Crawler.\nBackup 2: The Boyahda Tree L-9: Bark Spider, Death Cap.\nUse Sneak in Kuftal and avoid Guivre. Bring Dispel; Boyahda backup needs link control, Erase and status recovery.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 58–59", note: "Recommended: Cape Teriggan I-8/I-9/H-8: Robber Crab.\nBackup 1: The Boyahda Tree G-8/E-6/D-4: Robber Crab, Knight Crawler (wiki 57–59).\nBackup 2: Attohwa Chasm G-9/F-6: Monarch Ogrefly, Sand Lizard (wiki 58–60).\nBring Dispel. Stay clear of higher-level cockatrices in Teriggan; Attohwa needs strong area healing.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 64–66", note: "Recommended: Bibiki Bay G-6: Tragopan.\nBackup 1: Labyrinth of Onzozo H-6/I-6: Torama.\nBackup 2: Attohwa Chasm F-7: Tracker Antlion.\nBirds link by sight. Torama needs Silence/Paralysis recovery and Ose avoidance; antlions need Blindna/Erase.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
            GuideStep(kind: "L", title: "Levels 70–75", note: "Recommended: Cape Teriggan G-5: Greater Manticore.\nBackup 1: Newton Movalpolos, exit from Mine Shaft #2716: moblins, bugbears.\nBackup 2: Kuftal Tunnel map 3 H-6/I-8: Ovinnik, Greater Cockatrice.\nBring Erase and keep mages away from Riddle. Newton is a roaming camp via Twinkbrix teleport; Kuftal access depends on moving boulder and needs Stona/Paralyna.\nDraft: wiki-sourced, not verified in game. Ranking depends on composition, travel and competition.\nSource: https://horizonffxi.wiki/EXP_Camps (checked 2026-10-30).", fixed: true, tags: ["SRC": "https://horizonffxi.wiki/EXP_Camps"]),
        ], server: "HorizonXI")
}
